const normalize=s=>String(s||'').normalize('NFKC').toLowerCase();
async function api(url,method='GET',body){
  // Distinguish a disconnected server or non-JSON response from a rejected request.
  let r;try{r=await fetch(url,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined})}catch{throw Error(t('serverDisconnected'))}
  let data;try{data=await r.json()}catch{const e=Error(`${t('serverResponseError')} (HTTP ${r.status})`);e.status=r.status;throw e}
  if(!r.ok){const e=Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data));e.status=r.status;throw e}return data
}
