function selectedSkill(){const [id,p]=$('skillSelect').value.split('|');return skills.find(x=>x.id===id&&x.points===Number(p))}
function skillConflict(req,ban){return req.some(s=>ban.some(b=>b.id===s.id&&(b.points<0?s.points<=b.points:s.points>=b.points)))}
function addSkill(list){const s=selectedSkill();if(!s)return;const proposed=list.filter(x=>x.id!==s.id);proposed.push({...s,weight:1});if(skillConflict(list===required?proposed:required,list===forbidden?proposed:forbidden)){message(t('presetConflict'));return}list.splice(0,list.length,...proposed);renderSkills()}
function showSkillHelp(s){if(!s)return;const tiers=skillReference.filter(x=>x.id===s.id);if(!tiers.length)return;const selected=tiers.find(x=>x.points===(s.threshold??s.level??s.points))||tiers.find(x=>x.ja===(s.level_ja||s.ja))||tiers[0];$('skillHelpTitle').textContent=lang==='ja'?selected.family_ja:selected.family_en;const root=$('skillHelpBody');root.replaceChildren(el('p',t('skillReferenceHint'),'muted'));const table=el('table');row(table,[t('skills'),t('points'),t('detail')],true);for(const x of tiers){const notes=[];if(lang==='ja'&&x.description_ja)notes.push(x.description_ja);if(x.description_en)notes.push((lang==='ja'?'英語原文: ':'Ferias reference: ')+x.description_en);if(lang==='ja'&&!x.description_ja&&!x.description_en)notes.push('効果の詳細説明は未登録です。');if(x.target?.[lang])notes.push(`${t('targetSkill')}: ${x.target[lang]}`);for(const r of x.relations?.[lang]||[])notes.push(`${t(r.type==='ContainedSkills'?'contained':'deactivated')}: ${r.name}`);const tr=row(table,[name(x),x.points,notes.join(' / ')||t('skillNoDetail')]);if(x===selected)tr.classList.add('skill-current');}root.append(table);const link=el('a',t('skillSearchHelp'));link.href='https://www.google.com/search?q='+encodeURIComponent('MHF '+selected.family_ja+' スキル 効果');link.target='_blank';link.rel='noopener noreferrer';root.append(link);$('skillDialog').showModal()}
