function applySkillPreset(){const wt=$('wt').value,mode=$('skillPreset').value,ranged=['LBG','HBG','Bow'].includes(wt),r=[...required],o=[...optional],b=[...forbidden],missing=[];const add=(list,n,family=false,lowest=false)=>{const matches=skills.filter(s=>family?s.family_ja===n:s.ja===n).sort((a,b)=>lowest?a.points-b.points:b.points-a.points);const s=matches[0];if(!s){missing.push(n);return}const i=list.findIndex(x=>x.id===s.id);if(i<0)list.push({...s,weight:1});else if(lowest?s.points<list[i].points:s.points>list[i].points)list[i]={...s,weight:1}};if(mode==='futa'||mode==='nonfuta'){add(r,'剛撃+6');add(r,'豪放+3');if(mode==='futa')add(r,'不退ノ構');else{add(r,'一閃+3');add(b,'不退ノ構')}add(o,ranged?'装着':'剣神',true);add(o,'吸血',true)}else if(mode==='protection'){add(r,'豪放+3');for(const n of ['耳栓強化','風圧強化','耐震強化'])add(r,n,true,true)}else{add(o,secretFamilies[wt],true);for(const n of weaponSuggestions[wt]||[])add(o,n,true)}if(skillConflict(r,b)){message(t('presetConflict'));return}required=r;optional=o.filter(s=>!r.some(x=>x.id===s.id)&&!b.some(x=>x.id===s.id&&(x.points<0?s.points<=x.points:s.points>=x.points)));forbidden=b;if(mode==='weapon')$('objective').value='optional';renderSkills();message(missing.length?t('presetUnavailable')+': '+missing.join(' / '):t('saved'))}
