// A search belongs to this browser tab; session storage survives refresh but not a new browser session.
const LAST_SEARCH='mhf.lastSearch', ACTIVE_SEARCH='mhf.activeSearch';
function sessionRead(key){try{return JSON.parse(sessionStorage.getItem(key)||'null')}catch{return null}}
function sessionWrite(key,value){try{if(value===null)sessionStorage.removeItem(key);else sessionStorage.setItem(key,JSON.stringify(value))}catch{}}
function activeRecord(){const x=sessionRead(ACTIVE_SEARCH);return x&&typeof x.id==='string'&&/^[a-f0-9]{32}$/.test(x.id)&&validProfileState(x.state)?x:null}
function setActiveRecord(value){sessionWrite(ACTIVE_SEARCH,value);$('resumeJob').hidden=!value}
function busy(on){$('run').disabled=on;$('probe').disabled=on;$('cancel').disabled=!on;document.querySelectorAll('nav button,#resultCards button,#comparison button,#saveProfile,#loadProfile,#deleteProfile,#openImport,#exportCurrent,#backupSave,#backupOpen,#restoreLast,#resumeJob').forEach(b=>b.disabled=on);if(!on){$('profileSelect').onchange();$('restoreLast').disabled=!validProfileState(sessionRead(LAST_SEARCH));$('resumeJob').hidden=!activeRecord()}}
async function followJob(record){
  currentJob=record.id;setActiveRecord(record);$('resumeJob').hidden=true;$('cancel').disabled=false;
  const gen=++generation;
  while(gen===generation){const status=await api('/api/search/'+record.id);if(gen!==generation)return;
    if(status.status==='running'){message(`${t('searching')} · ${status.elapsed_seconds}s`);await new Promise(r=>setTimeout(r,750));continue}
    setActiveRecord(null);
    if(status.status==='done'){result=status.result;comparisonKeys.clear();resetResultFilters();message('');renderResults();$('results').scrollIntoView({block:'start',behavior:'smooth'})}
    else if(status.status==='cancelled')message(t('cancelled'));else throw Error(status.detail||status.status);break
  }
}
async function resumeSearch(){const record=activeRecord();if(!record)return;busy(true);try{restoreProfile({state:record.state});message(t('resuming'));await followJob(record)}catch(e){if(e.status===404){setActiveRecord(null);message(t('jobExpired'))}else message(e.message)}finally{currentJob=null;busy(false)}}
async function run(probe=false){try{
  if(activeRecord()){await resumeSearch();return}
  const b=makeBuild(tab!=='manual');if(tab==='manual'){busy(true);$('cancel').disabled=true;try{manualHit=await api('/api/evaluate','POST',b);renderResults()}finally{busy(false)}return}
  if(probe)b.probe={seconds:b.seconds,candidate_limit:12};const state=snapshot();sessionWrite(LAST_SEARCH,state);
  // Persist the client-generated ID before sending the request, so a lost response is recoverable.
  const id=Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
  const record={id,state};setActiveRecord(record);
  busy(true);$('cancel').disabled=true;message(t('searching'));
  try{await api('/api/search','POST',{...b,_job_id:id})}catch(e){
    // A confirmed rejection did not create this job; an ambiguous network failure may have.
    if(e.status>=400&&e.status<500)setActiveRecord(null);
    throw e;
  }
  await followJob(record);
}catch(e){if(e.status===404&&activeRecord()){setActiveRecord(null);message(t('jobExpired'))}else message(e.message)}finally{currentJob=null;busy(false)}}
async function cancel(){if(!currentJob)return;try{await api('/api/search/'+currentJob,'DELETE');generation++;setActiveRecord(null);message(t('cancelled'));currentJob=null;}catch(e){message(e.message)}}
