function resultMatches(hit,f){const r=hit.evaluation||{},m=hit.metrics||{},d=hit.display||{};const items=Object.values(d.items||{}).filter(Boolean),active=(r.skills||[]).filter(s=>s.status==='active');const text=[d.weapon?.ja,d.weapon?.en,...items.flatMap(s=>[s.ja,s.en]),...active.flatMap(s=>[s.level_ja,s.level_en,s.ja,s.en]),...(r.zenith||[]).filter(s=>s.level>0&&s.has_base_skill!==false).flatMap(s=>[s.ja,s.en]),...(r.automatic||[]).filter(s=>s.effective!==false).flatMap(s=>[s.ja,s.en])].filter(Boolean).join(' ').normalize('NFKC').toLowerCase();if(f.q.normalize('NFKC').toLowerCase().trim().split(/\s+/).filter(Boolean).some(q=>!text.includes(q)))return false;if(f.free>0&&!(Number.isFinite(m.free_jewel_slots)&&m.free_jewel_slots>=f.free))return false;if(f.res>0&&['Fire','Water','Thunder','Ice','Dragon'].filter(k=>Number.isFinite(m['res_'+k])&&m['res_'+k]>=55).length<f.res)return false;if(f.super&&((r.protection||[]).filter(p=>p.super_protection===true).length!==3))return false;if(f.optional&&(!(m.optional||[]).length||!m.optional.every(s=>s.achieved===true)))return false;return true}
