function renderResults(){renderComparison();const root=$('resultCards');root.replaceChildren();$('sortWrap').hidden=tab!=='search';$('resultFilters').hidden=tab!=='search'||!result||result.auto_candidates!==undefined;$('resultTitle').textContent=t(tab==='favorites'?'favorites':'results');$('resultSummary').textContent='';$('favoriteFilters').hidden=tab!=='favorites';if(tab==='favorites'){if(!favorites.length)root.append(el('p',t('noFavorites'),'muted'));favorites.forEach((h,i)=>{const filter=$('favoriteGroup').value;if(filter!=='*'&&filter!==favoriteCategory(h))return;const c=renderHit(h,i+1);c.prepend(el('h3',`${h.title||t('candidate')+' '+(i+1)} · ${h.category||t('uncategorized')}`));c.append(button(t('rename'),()=>{const n=prompt(t('favoriteName'),h.title||'');if(n===null)return;const g=prompt(t('favoriteGroup'),h.category||'');if(g===null)return;h.title=n.trim();h.category=g.trim();persist('mhf.favorites',favorites);renderFavoriteFilters();renderResults()}),button(t('remove'),()=>{favorites.splice(i,1);persist('mhf.favorites',favorites);renderFavoriteFilters();renderResults()}));root.append(c)});return}if(tab==='manual'){if(manualHit)root.append(renderHit(manualHit));return}if(!result)return;const list=result.results||[];$('resultSummary').textContent=`${list.length} · ${t(result.status||'probe')} · ${result.elapsed_seconds??'—'}s`;if(result.auto_candidates!==undefined){$('resultSummary').textContent+=' · '+t('probeHint');for(const h of list){const s=skills.find(x=>x.id===h.target.skill&&x.points===h.target.points);root.append(el('h3',`${s?name(s):h.target.skill} · ${t(h.status)}`));if(h.witness)root.append(renderHit(h.witness))}return}if(result.live_sample)root.append(el('p',t('liveHint')+' '+t('liveSampleOrder'),'muted'));if(result.search_passes){root.append(el('p',result.search_passes.map(p=>(lang==='ja'?({prioritized:'優先探索',full:'全候補探索',focused:'関連珠探索'}[p.pool]||p.pool):p.pool)+' '+p.count+' '+(lang==='ja'?'件':'hits')+' · '+t(p.status)).join(' → '),'muted'))}if(result.weapon_groups!==undefined){root.append(el('p',(lang==='ja'?'武器グループ探索：':'Weapon groups: ')+result.weapon_groups_searched+'/'+result.weapon_groups+(lang==='ja'?'（未探索 '+result.weapon_groups_untested+'）':' (untested '+result.weapon_groups_untested+')'),'muted'))}if(result.pool_counts){const counts=Object.values(result.pool_counts).reduce((a,b)=>a+b,0);root.append(el('p',lang==='ja'?`探索対象 ${counts.toLocaleString()} 件 · ソルバー試行 ${result.attempts??0} 回 · 再検証除外 ${result.rejected??0} 件 · 発動枠追加制約 ${result.slot_cuts??0} 件`:`Candidate pool ${counts.toLocaleString()} · Solver attempts ${result.attempts??0} · Rejected ${result.rejected??0} · Slot constraints ${result.slot_cuts??0}`,'muted'))}if(result.status==='time_limit'||result.status==='partial_weapon_search'||result.pool_mode==='prioritized'||result.pool_mode==='focused'){root.append(el('p',lang==='ja'?'探索範囲・時間・結果件数に上限があります。条件を満たす別の構成が存在する可能性があります。':'Search is bounded by pool, time and result limits. Other valid builds may exist.','muted'))}if(!list.length){root.append(el('p',t('noResults')));if(!$('fullJewels').checked)root.append(el('p',lang==='ja'?'必要に応じて「装飾品・カフを広く探索」を有効にするか、探索時間を延ばしてください。':'Try the wide jewel and cuff pool or allow more search time.','muted'));return}const key=$('sort').value,desc=['active_normal_skills','free_jewel_slots','optional_score','defense','resistance_sum',...statKeys.slice(1).map(k=>'res_'+k)].includes(key);const sorted=list.filter(h=>resultMatches(h,resultFilterState())).sort((a,b)=>{if(key==='rank')return a.rank-b.rank;const x=a.metrics?.[key],y=b.metrics?.[key];if(!Number.isFinite(x))return Number.isFinite(y)?1:0;if(!Number.isFinite(y))return -1;return (desc?-1:1)*(x-y)});$('resultSummary').textContent+=` · ${sorted.length}/${list.length}`;if(!sorted.length)root.append(el('p',t('noFiltered'),'muted'));sorted.forEach((h,i)=>root.append(renderHit(h,h.rank??i+1)))}
async function loadHit(hit){try{switchTab('manual');const b=hit.build,lookup=id=>({id,...hit.display?.items?.[id]});$('wt').value=b.weapon_type;$('sex').value=b.sex;$('gPoogie').checked=!!b.g_poogie;$('pClothes').checked=!!b.premium_poogie_clothes;armor={};for(const [p,a] of Object.entries(b.armor)){const it=lookup(a.item);armor[p]={...it,level:a.level,levels:await api('/api/levels?id='+encodeURIComponent(it.id)),jewels:(a.jewels||[]).map(lookup)}}weapon=b.weapon?.page?{...hit.display?.weapon,page:b.weapon.page,anchor:b.weapon.anchor,ja:hit.display?.weapon?.name_ja||hit.display?.weapon?.name_source,en:hit.display?.weapon?.name_source,jewels:(b.weapon.jewels||[]).map(lookup)}:null;$('weaponMode').value=weapon?'fixed':'none';$('sigils').value=String(b.weapon?.sigils||0);restoreExternal(b.external);cuffs=(b.cuffs||[]).map(lookup);$('fixCuffs').checked=true;manualHit=hit;switchTab('manual');window.scrollTo(0,0);return true}catch(e){message(e.message);return false}}
