let workspace='skills';
const workspaceByTab={search:'skills',manual:'gear'};
function selectWorkspace(key){
 const old=workspace;
 if(!switchingView&&desktopInitialized&&old!==key)workspaceScroll[tab+':'+old]=window.scrollY;
 if(tab==='manual'&&['skills','conditions'].includes(key))key='gear';
 workspace=key;
 if(tab==='search'||tab==='manual')workspaceByTab[tab]=key;
 for(const b of document.querySelectorAll('[data-workspace-tab]')){b.hidden=tab==='manual'&&['skills','conditions'].includes(b.dataset.workspaceTab);b.setAttribute('aria-selected',String(b.dataset.workspaceTab===key));b.tabIndex=b.dataset.workspaceTab===key?0:-1;}
 for(const panel of document.querySelectorAll('[data-workspace]'))panel.hidden=panel.dataset.workspace!==key;
 refreshWorkspaceOverview();
 if(!switchingView&&desktopInitialized&&old!==key){const y=workspaceScroll[tab+':'+key];if(y!==undefined){const token=++restoreScrollToken;requestAnimationFrame(()=>{if(token===restoreScrollToken&&workspace===key)window.scrollTo(0,y)})}saveViewSoon()}
}
function refreshWorkspaceOverview(){const root=$('workspaceOverview');if(!root)return;const jp=lang==='ja';const mode=$('weaponMode').value;const wt=weaponTypes.find(x=>x[0]===$('wt').value);const statCount=statKeys.filter(k=>$('min_'+k).value!=='').length;
 const vals=[wt?.[jp?1:2]||$('wt').value,`${t('required')} ${required.length}`,`${t('optional')} ${optional.length}`,`${t('forbidden')} ${forbidden.length}`,`${jp?'固定防具':'Fixed armor'} ${Object.keys(armor).length}/5`,`${jp?'耐性・防御条件':'Stat filters'} ${statCount}`, $('bountyGroup').value|| (jp?'通常検索':'Normal search'), $('extMeal').value!=='none'||extRoadKeys.some(k=>Number($('road_'+k).value)>0)?(jp?'外部効果あり':'External effects on'):(jp?'外部効果なし':'No external effects')];root.replaceChildren(...vals.map(v=>el('span',v,'workspace-tag')));}
for(const b of document.querySelectorAll('[data-workspace-tab]')){b.onclick=()=>selectWorkspace(b.dataset.workspaceTab);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-workspace-tab]:not([hidden])')];const i=tabs.indexOf(b);const next=tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];selectWorkspace(next.dataset.workspaceTab);next.focus()};}
$('editor').addEventListener('change',refreshWorkspaceOverview);
// Keep the last editor independent of the visible tab (favorites and inventory have no editor).
let editorOwner='search';
const editorStates={}, tabViews={}, workspaceScroll={};
let switchingView=false, restoreScrollToken=0;
function captureView(key){
 const details=[...$('resultCards').querySelectorAll('details')].map(d=>d.open);
 tabViews[key]={y:window.scrollY,details,skillScroll:$('skillRows').scrollTop,open:Object.fromEntries([...document.querySelectorAll('details[id]')].filter(d=>!d.closest('[hidden]')).map(d=>[d.id,d.open]))};
}
function restoreView(key){
 const view=tabViews[key];const token=++restoreScrollToken;
 if(!view)return;
 [...$('resultCards').querySelectorAll('details')].forEach((d,i)=>{d.open=!!view.details[i]});
 $('skillRows').scrollTop=view.skillScroll||0;for(const [id,open] of Object.entries(view.open||{})){const d=$(id);if(d?.tagName==='DETAILS')d.open=!!open}
 requestAnimationFrame(()=>{if(token===restoreScrollToken&&tab===key)window.scrollTo(0,view.y||0)});
}
function switchTab(next,transfer=false){
 const previous=tab, changed=previous!==next;
 if(changed&&desktopInitialized)captureView(previous);
 switchingView=true;
 try{
  if((next==='search'||next==='manual')&&next!==editorOwner&&desktopInitialized){
   const state=snapshot();editorStates[editorOwner]=state;
   editorOwner=next;
   if(!transfer&&editorStates[next])applyProfileState(editorStates[next]);
   else if(!transfer&&next==='manual'){
    // First visit starts from the current equipment, but later changes are independent.
    if($('weaponMode').value==='auto')$('weaponMode').value='none';
   }
  }
  tab=next;document.querySelectorAll('nav button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));
  $('editor').hidden=['favorites','inventory'].includes(tab);$('inventoryPanel').hidden=tab!=='inventory';$('results').hidden=tab==='inventory';
  if(tab==='inventory')renderInventory();if(tab==='favorites')renderFavoriteFilters();
  $('skillSettings').hidden=tab==='manual';$('exclusions').hidden=tab==='manual';$('probe').hidden=tab==='manual';$('run').textContent=t(tab==='manual'?'evaluate':'run');
  renderEquipment();renderResults();if(tab==='search'||tab==='manual')selectWorkspace(workspaceByTab[tab]);
  if(changed)restoreView(next);
 }finally{switchingView=false}
 if(changed&&desktopInitialized){if(tab!=='search'){if(live.task||live.pending||live.timer!==null)pauseLiveForTab()}else scheduleLive();saveViewSoon()}
 paintLiveCounts();
}
