$('saveProfile').onclick=()=>{const n=prompt(t('profileName'),'');if(n===null||!n.trim())return;const i=profiles.findIndex(p=>p.name===n.trim());const p={name:n.trim(),state:snapshot()};if(i>=0){if(!confirm(lang==='ja'?'同名の条件を上書きしますか？':'Overwrite this preset?'))return;profiles[i]=p}else profiles.push(p);persist('mhf.profiles',profiles);renderProfiles();$('profileSelect').value=String(i>=0?i:profiles.length-1);$('profileSelect').onchange()};
