// Replacement keeps all other fixed equipment and jewel placements. For a replaced armor, its jewels return to the search pool.
async function prepareAlternative(hit,part,jewel){if(!await loadHit(hit))return;required=[];optional=[];const r=hit.evaluation;for(const s of r.skills.filter(s=>s.status==='active'&&(s.threshold>0||s.level_ja==='青魂'))){const v=skills.find(x=>x.id===s.id&&x.points===s.threshold);if(v)required.push({...v,weight:1})}for(const s of r.zenith.filter(s=>s.level>0&&s.has_base_skill!==false)){const v=skills.filter(x=>x.id===s.id&&x.points<=s.level).sort((a,b)=>b.points-a.points)[0];if(v)required.push({...v,weight:1})}if(part){const id=armor[part]?.id;if(!id)return;excluded=excluded.filter(x=>x.id!==id);excluded.push({id,ja:itemName(hit,id),en:hit.display?.items?.[id]?.en});delete armor[part]}else if(jewel){for(const a of [...Object.values(armor),...(weapon?[weapon]:[])])a.jewels=a.jewels.filter(j=>j.id!==jewel);excluded=excluded.filter(x=>x.id!==jewel);excluded.push({id:jewel,ja:itemName(hit,jewel),en:hit.display?.items?.[jewel]?.en})} $('diverseArmor').checked=!!part;renderExcluded();renderSkills();switchTab('search',true);message(t('altReady'))}
function replacementUI(hit){const d=el('details');d.append(el('summary',t('alternative')),el('p',t('altHint'),'muted'));const b=hit.build;const a=el('div',null,'actions');for(const p of parts)if(b.armor[p])a.append(button(t(p),()=>prepareAlternative(hit,p,null)));d.append(a);const j=el('select');const ids=[...new Set([...Object.values(b.armor),b.weapon||{}].flatMap(x=>x.jewels||[]))];j.append(...ids.map(id=>option(id,itemName(hit,id))));if(ids.length){const r=el('div',null,'actions');r.append(j,button(t('altJewel'),()=>prepareAlternative(hit,null,j.value)));d.append(r)}return d}
