async function refreshBounty(){const seq=++bountySequence,root=$('bountyInfo'),g=$('bountyGroup').value;root.replaceChildren();if(!g)return;root.textContent=t('bountyLoading');try{const r=await api('/api/bounty?'+new URLSearchParams({group:g,number:$('bountyNumber').value,mode:$('bountyMode').value}));if(seq!==bountySequence)return;const jp=lang==='ja';root.replaceChildren(el('strong',t('bountyPartial')));const lines=[];if(r.armor_ranks)lines.push((jp?'防具ランク: ':'Armor rank: ')+r.armor_ranks.join(', '));if(r.armor_prefix)lines.push((jp?'防具指定: ':'Armor series: ')+r.armor_prefix);if(r.no_paid_armor)lines.push(jp?'課金系防具除外':'Exclude paid armor');if(r.cuff!=='any')lines.push(jp?(r.cuff==='none'?'カフ禁止':'G級カフのみ'):(r.cuff==='none'?'No cuffs':'G-rank cuffs only'));if(r.no_secret)lines.push(jp?'秘伝禁止':'No secret skills');if(r.no_futai)lines.push(jp?'不退禁止':'No Futaigeki');if(r.secret_weapon)lines.push((jp?'秘伝禁止対象: ':'Secret prohibited: ')+r.secret_weapon);if(r.weapon_types_deny.length)lines.push((jp?'禁止武器種: ':'Prohibited types: ')+r.weapon_types_deny.map(k=>weaponTypes.find(x=>x[0]===k)?.[jp?1:2]||k).join(', '));if(r.max_rarity!==null)lines.push((jp?'武器レア度上限: ':'Max weapon rarity: ')+r.max_rarity);if(r.armor_max_rarity!==null)lines.push((jp?'防具レア度上限: ':'Max armor rarity: ')+r.armor_max_rarity);if(r.weapon_allow)lines.push((jp?'武器系統許可: ':'Allowed weapon categories: ')+r.weapon_allow.join(', '));if(r.weapon_deny.length)lines.push((jp?'武器系統禁止: ':'Prohibited weapon categories: ')+r.weapon_deny.join(', '));if(r.no_sigils)lines.push(jp?'シジル禁止':'No sigils');for(const l of lines)root.append(el('div',l));for(const w of r.warnings)root.append(el('p',w[lang],'muted'))}catch(e){if(seq===bountySequence)root.textContent=e.message}}
