function backupData(){return {favorites,inventory:owned,profiles,collection,materials:materialState,lang,theme:document.documentElement.classList.contains('light')?'light':'dark'}}
// Serialize logical backup writes; retain the existing browser-only path unchanged.
let desktopQueue=Promise.resolve(),desktopInitialized=false;
function desktopSnapshot(raw){
  const bridge=window.pywebview?.api;
  if(!bridge?.save_backup||(!desktopInitialized&&!raw))return Promise.resolve();
  try{
    const value=raw||makeBackup(backupData());validateBackup(value);
    const text=JSON.stringify(value);
    desktopQueue=desktopQueue.catch(()=>{}).then(()=>bridge.save_backup(text)).catch(e=>console.warn('Desktop backup failed',e));
    return desktopQueue;
  }catch(e){console.warn('Desktop backup failed',e);return Promise.resolve()}
}
function desktopReady(){
  const bridge=window.pywebview?.api;
  if(!desktopInitialized||!bridge)return;
  desktopSnapshot().then(()=>bridge.startup_ready?.()).catch(e=>console.warn('Startup report failed',e));
}
window.addEventListener('pywebviewready',desktopReady);
$('backupSave').onclick=()=>{try{const b=makeBackup(backupData());validateBackup(b);downloadLocal(JSON.stringify(b,null,2),'mhf-backup-'+new Date().toISOString().slice(0,10)+'.json','application/json');shareStatus(t('saved'))}catch(e){shareStatus(e.message)}};
$('backupOpen').onclick=()=>$('backupFile').click();$('backupFile').onchange=async()=>{const f=$('backupFile').files[0];$('backupFile').value='';if(!f)return;if(f.size>12000000){shareStatus(t('fileTooLarge'));return}try{const raw=JSON.parse(await f.text()),d=validateBackup(raw);const counts=`${t('favorites')}: ${d.favorites.length}, ${t('inventory')}: ${Object.keys(d.inventory).length}, ${t('profiles')}: ${d.profiles.length}, ${t('weaponCollection')}: ${d.collection?.weapons.length||0}, ${t('sigilCollection')}: ${d.collection?.sigils.length||0}`;if(!confirm(counts+'\n'+t('restoreConfirm')))return;restoreBackup(localStorage,raw);await desktopSnapshot(raw);shareStatus(t('restoreDone'));location.reload()}catch(e){shareStatus(e.message)}};
