 const sample=$('liveSampleList');sample.hidden=!live.enabled||!hits.length;
 sample.replaceChildren(...hits.slice(0,3).map((h,i)=>el('div',`#${i+1} · ${Object.values(h.build.armor||{}).map(a=>name(h.display?.items?.[a.item])||a.item).join(' / ')}`,'muted')));

