// Native desktop settings. Browser-only mode never exposes the native bridge controls.
(function desktopInformation(){
  const tr=(ja,en)=>lang==='ja'?ja:en;
  const bridge=()=>window.pywebview?.api;
  const open=$('desktopInfoOpen'), dialog=$('desktopInfoDialog');
  const controls=['desktopInfoSave','desktopInfoCheck','desktopInfoStartup','desktopInfoChannel'];
  let busy=false, valid=false;
  function labels(){
    open.textContent=$('desktopInfoTitle').textContent=tr('設定・バージョン情報','Settings / About');
    $('desktopInfoStartupLabel').textContent=tr('起動時に更新を確認する','Check for updates at startup');
    $('desktopInfoChannelLabel').textContent=tr('更新チャンネル','Update channel');
    $('desktopInfoSave').textContent=tr('設定を保存','Save settings');
    $('desktopInfoCheck').textContent=tr('最新版を確認','Check for updates');
    $('desktopInfoBackupTitle').textContent=tr('バックアップ・復元状況','Backup / recovery');
    $('desktopInfoHistoryTitle').textContent=tr('更新履歴（最大30件）','Update history (up to 30 entries)');
  }
  function status(text){$('desktopInfoStatus').textContent=text}
  function lock(value){busy=value;for(const id of controls)$(id).disabled=busy||!valid;}
  function field(label,value){const r=el('div',null,'desktop-info-field');r.append(el('span',label,'muted'),el('strong',value));return r}
  function yes(value){return value?tr('あり','Available'):tr('なし','Not available')}
  function render(info){
    const unknown=tr('確認できません','Unknown');
    $('desktopInfoVersions').replaceChildren(field(tr('アプリ本体','Application'),info.app||unknown),field(tr('実行中のランチャー','Running launcher'),info.launcher||unknown));
    valid=!info.config_error;
    $('desktopInfoOptions').hidden=!valid;
    if(valid){$('desktopInfoStartup').checked=!!info.startup;$('desktopInfoChannel').value=info.channel;}
    $('desktopInfoBackups').replaceChildren(field(tr('自動バックアップ','Automatic backups'),`${info.backups} / 5`),field(tr('更新前の保存データ','Pre-update checkpoint'),yes(info.checkpoint)),field(tr('旧アプリ本体','Previous app'),yes(info.previous_app)),field(tr('旧ランチャー','Previous launcher'),yes(info.previous_launcher)));
    const history=$('desktopInfoHistory');history.replaceChildren();
    const names={installed:tr('アプリ更新','App updated'),launcher_installed:tr('ランチャー更新','Launcher updated'),rollback:tr('旧版へ復元','Rolled back')};
    for(const row of info.history||[]){const date=new Date(row.at);const when=Number.isNaN(date.getTime())?row.at:date.toLocaleString(lang==='ja'?'ja-JP':'en-US');history.append(field(`${when} · ${names[row.status]||row.status}`,row.version));}
    if(!history.childElementCount)history.append(el('p',tr('更新履歴はまだありません。','No update history yet.'),'muted'));
    if(!valid)status(tr('更新設定を読み込めません。release_source.json を確認してください。','Could not read release_source.json.'));
  }
  function available(){open.hidden=!bridge()?.version_information;labels()}
  window.addEventListener('pywebviewready',available);
  $('lang').addEventListener('change',labels);
  available();
  open.onclick=async()=>{if(busy)return;labels();status(tr('読み込み中…','Loading…'));valid=false;lock(true);$('desktopInfoOptions').hidden=true;for(const id of ['desktopInfoVersions','desktopInfoBackups','desktopInfoHistory'])$(id).replaceChildren();dialog.showModal();try{const info=await bridge().version_information();status('');render(info)}catch(e){status(tr('情報を読み込めませんでした。','Unable to read desktop information.'))}finally{lock(false)}};
  $('desktopInfoSave').onclick=async()=>{if(busy||!valid)return;lock(true);try{await bridge().configure_updates($('desktopInfoStartup').checked,$('desktopInfoChannel').value);status(tr('設定を保存しました。','Settings saved.'))}catch(e){status(tr('設定を保存できませんでした。','Could not save settings.'))}finally{lock(false)}};
  $('desktopInfoCheck').onclick=async()=>{if(busy||!valid)return;lock(true);status(tr('最新版を確認中…','Checking for updates…'));try{const result=await bridge().discover_updates();const info=await bridge().version_information();if(result.status==='available'){status(tr(`新しい配布版 ${result.version} があります。署名確認と更新は次回の通常起動時に行います。${info.startup?'アプリを完全終了して再起動してください。':'起動時の更新確認を有効にして保存してください。'}`,`Release ${result.version} is available. Signature verification and installation occur at the next foreground launch. ${info.startup?'Fully exit and restart.':'Enable startup update checks and save.'}`))}else if(result.status==='no_compatible_release'){status(tr('新しい対応済み配布版はありません。','No newer compatible release found.'))}else{status(tr('更新情報を取得できません。現在の版を使用できます。','Unable to retrieve release information. You can keep using this version.'))}}catch(e){status(tr('更新確認に失敗しました。','Update check failed.'))}finally{lock(false)}};
})();
